import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";

function Register() {
  const location = useLocation();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });

  const [userId, setUserId] = useState("");
  const [qrData, setQrData] = useState("");
  const [photo, setPhoto] = useState("");
  const [loading, setLoading] = useState(false);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  /* =============================
     LOAD RAZORPAY SCRIPT
  ============================= */
  useEffect(() => {
    const script = document.createElement("script");
    script.src = "https://checkout.razorpay.com/v1/checkout.js";
    script.async = true;
    document.body.appendChild(script);
    return () => document.body.removeChild(script);
  }, []);

  /* =============================
     INPUT CHANGE
  ============================= */
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* =============================
     PAY & REGISTER
  ============================= */
  const handlePayment = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      // Step 1: Create Razorpay order from backend
      const orderRes = await axios.post("http://localhost:5000/create-order", {
        amount: 1, // ₹1
      });

      const { orderId, amount, currency, key } = orderRes.data;

      // Step 2: Open Razorpay payment popup
      const options = {
        key,                   // Your Razorpay Key ID from backend
        amount,                // in paise (100 = ₹1)
        currency,
        name: "College Event",
        description: `Registration for ${eventName}`,
        order_id: orderId,
        prefill: {
          name: formData.name,
          email: formData.email,
          contact: formData.phone,
        },
        theme: { color: "#6366f1" },

        handler: async function (response) {
          // Step 3: Verify payment on backend & register user
          try {
            const verifyRes = await axios.post("http://localhost:5000/verify-payment", {
              razorpay_order_id: response.razorpay_order_id,
              razorpay_payment_id: response.razorpay_payment_id,
              razorpay_signature: response.razorpay_signature,
              ...formData,
              photo,
            });

            if (verifyRes.data.success) {
              setUserId(verifyRes.data.userId);
              setQrData(verifyRes.data.qrData);
              alert("Payment Verified! Registration Successful.");
            } else {
              alert("Payment verification failed. Contact support.");
            }
          } catch {
            alert("Verification error. Please contact support.");
          }
        },

        modal: {
          ondismiss: () => {
            setLoading(false);
            alert("Payment cancelled.");
          },
        },
      };

      const rzp = new window.Razorpay(options);
      rzp.open();
      setLoading(false);
    } catch (err) {
      setLoading(false);
      alert("Failed to initiate payment. Try again.");
    }
  };

  /* =============================
     OPEN CAMERA
  ============================= */
  const openCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
      streamRef.current = stream;
      videoRef.current.srcObject = stream;
      videoRef.current.play();
    } catch {
      alert("Camera access denied");
    }
  };

  /* =============================
     CAPTURE PHOTO
  ============================= */
  const capturePhoto = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(video, 0, 0);
    const image = canvas.toDataURL("image/png");
    setPhoto(image);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
    }
  };

  /* =============================
     DOWNLOAD ID CARD
  ============================= */
  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = "Event_ID_Card.png";
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  return (
    <div>
      <Navbar />
      <div style={{ textAlign: "center", padding: "20px" }}>
        <h2>Event Registration</h2>

        {/* FORM */}
        {!qrData && (
          <form onSubmit={handlePayment}>
            <input name="name" placeholder="Name" onChange={handleChange} required /><br /><br />
            <input name="college_name" placeholder="College Name" onChange={handleChange} required /><br /><br />
            <input name="phone" placeholder="Phone" onChange={handleChange} required /><br /><br />
            <input name="email" placeholder="Email" onChange={handleChange} required /><br /><br />
            <h3>Selected Event: {eventName}</h3>
            <button type="submit" disabled={loading}>
              {loading ? "Processing..." : "Pay ₹1 & Register"}
            </button>
          </form>
        )}

        {/* QR AFTER REGISTER */}
        {qrData && (
          <div>
            <h3>Your QR Code</h3>
            <QRCode value={qrData.toString()} size={200} />
            <br /><br />
            <button onClick={openCamera}>Open Camera</button>
            <br /><br />
            <video ref={videoRef} width="320" height="240" style={{ border: "2px solid black" }} />
            <br /><br />
            <button onClick={capturePhoto}>Capture Photo</button>
            <canvas ref={canvasRef} style={{ display: "none" }} />
          </div>
        )}

        {/* ID CARD */}
        {photo && (
          <div style={{ marginTop: "30px" }}>
            <div
              ref={idCardRef}
              style={{
                border: "2px solid black",
                width: "300px",
                margin: "auto",
                padding: "15px",
                borderRadius: "10px",
              }}
            >
              <h3>College Event ID Card</h3>
              <p>Name : {formData.name}</p>
              <p>User ID : {userId}</p>
              <p>Event : {eventName}</p>
              <QRCode value={qrData.toString()} size={120} />
              <br /><br />
              <img src={photo} alt="User" width="120" />
            </div>
            <br />
            <button onClick={downloadCard}>Download ID Card</button>
          </div>
        )}
      </div>
    </div>
  );
}

export default Register;
